use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclenum! {
# [doc = " This type is used within both `ast::MetaItemLit` and `hir::Lit`."] # [doc = ""] # [doc = " Note that the entire literal (including the suffix) is considered when"] # [doc = " deciding the `LitKind`. This means that float literals like `1f32` are"] # [doc = " classified by this type as `Float`. This is different to `token::LitKind`"] # [doc = " which does *not* consider the suffix."] # [derive (Clone , Copy , Encodable , Decodable , Debug , Hash , Eq , PartialEq , HashStable_Generic)] pub enum LitKind { # [doc = " A string literal (`\"foo\"`). The symbol is unescaped, and so may differ"] # [doc = " from the original token's symbol."] Str (Symbol , StrStyle) , # [doc = " A byte string (`b\"foo\"`). The symbol is unescaped, and so may differ"] # [doc = " from the original token's symbol."] ByteStr (ByteSymbol , StrStyle) , # [doc = " A C String (`c\"foo\"`). Guaranteed to only have `\\0` at the end. The"] # [doc = " symbol is unescaped, and so may differ from the original token's"] # [doc = " symbol."] CStr (ByteSymbol , StrStyle) , # [doc = " A byte char (`b'f'`)."] Byte (u8) , # [doc = " A character literal (`'a'`)."] Char (char) , # [doc = " An integer literal (`1`)."] Int (Pu128 , LitIntType) , # [doc = " A float literal (`1.0`, `1f64` or `1E10f64`). The pre-suffix part is"] # [doc = " stored as a symbol rather than `f64` so that `LitKind` can impl `Eq`"] # [doc = " and `Hash`."] Float (Symbol , LitFloatType) , # [doc = " A boolean literal (`true`, `false`)."] Bool (bool) , # [doc = " Placeholder for a literal that wasn't well-formed in some way."] Err (ErrorGuaranteed) , }
}